<?php $pageTitle='Messages';$subtitle='Website enquiries and customer requests.';$active='Messages';require __DIR__.'/_layout.php';$rows=db()->query('SELECT cm.*,u.email account_email FROM contact_messages cm LEFT JOIN users u ON u.id=cm.user_id ORDER BY cm.created_at DESC')->fetchAll();?><div class="card"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Interest</th><th>Message</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=ae($r['created_at'])?></td><td><strong><?=ae($r['name'])?></strong><br><?=ae($r['phone'])?><br><small><?=ae($r['email'])?></small></td><td><span class="pill blue"><?=ae($r['interest'])?></span></td><td style="max-width:400px;line-height:1.6"><?=nl2br(ae($r['message']))?></td><td><select class="select" onchange="statusMsg(<?=$r['id']?>,this.value)"><?php foreach(['new','read','replied','closed'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="empty">No messages yet.</td></tr><?php endif;?></tbody></table></div></div><script>async function statusMsg(id,status){const j=await api('message-status',{id,status});toast(j.message,j.ok)}</script><?php require __DIR__.'/_foot.php';?>
